js = r'''
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[data-tab-group]').forEach(group => {
    const buttons = group.querySelectorAll('[data-tab-target]');
    const panels = group.querySelectorAll('[data-tab-panel]');
    buttons.forEach(button => button.addEventListener('click', () => {
      const target = button.dataset.tabTarget;
      buttons.forEach(b => b.classList.toggle('active', b === button));
      panels.forEach(panel => panel.classList.toggle('active', panel.dataset.tabPanel === target));
    }));
  });

  document.querySelectorAll('[data-accordion]').forEach(acc => {
    acc.querySelectorAll('.faq-q').forEach(button => button.addEventListener('click', () => {
      const item = button.closest('.faq-item');
      acc.querySelectorAll('.faq-item').forEach(other => { if (other !== item) other.classList.remove('active'); });
      item.classList.toggle('active');
    }));
  });

  document.querySelectorAll('[data-carousel]').forEach(carousel => {
    const strip = carousel.querySelector('.testimonial-strip');
    const slides = carousel.querySelectorAll('.testimonial');
    const label = carousel.querySelector('[data-carousel-count]');
    let index = 0;
    const show = next => {
      index = (next + slides.length) % slides.length;
      strip.style.transform = `translateX(-${index * 100}%)`;
      if (label) label.textContent = `${index + 1} / ${slides.length}`;
    };
    carousel.querySelector('[data-prev]')?.addEventListener('click', () => show(index - 1));
    carousel.querySelector('[data-next]')?.addEventListener('click', () => show(index + 1));
    show(0);
  });

  document.querySelectorAll('[data-demo-toggle]').forEach(button => button.addEventListener('click', () => {
    const content = document.querySelector(button.dataset.demoToggle);
    content.classList.toggle('active');
    button.querySelector('span').textContent = content.classList.contains('active') ? '−' : '+';
  }));

  const observer = new IntersectionObserver(entries => entries.forEach(entry => {
    if (entry.isIntersecting) entry.target.classList.add('visible');
  }), { threshold: .12 });
  document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
});
'''


def nav_html(active):
    links = ''.join(f'<a class="{ "active" if file==active else ""}" href="{file}">{label}</a>' for file,label in nav)
    return f'''<nav class="nav"><div class="container nav-inner"><a class="brand" href="index.html"><span class="mark">LF</span><span>LearnForge</span></a><div class="links">{links}</div><a class="btn" href="#trial">Start Free Trial</a></div></nav>'''

def footer_html():
    groups = {
        'Explore':['Pricing','Example Schools','Product Demo'],
        'Company':['About us','Careers','Press','Partners','Newsletter'],
        'Support':['Help Center','Blog','Pricing','House Rules','Content Guidelines'],
        'Legal':['Privacy Policy','Terms of Use','Cookies Policy','Ethics Line','Accessibility']
    }
    cols = ''.join('<div><h4>'+k+'</h4>'+''.join(f'<a href="#">{x}</a>' for x in xs)+'</div>' for k,xs in groups.items())
    return f'''<footer class="footer"><div class="container footer-grid"><div><a class="brand" href="index.html"><span class="mark">LF</span><span>LearnForge</span></a><p>Human-led learning, global scale, and AI-assisted workflows for serious education businesses.</p></div>{cols}</div><div class="container" style="border-top:1px solid #2a2d38;margin-top:34px;padding-top:22px;color:#aeb4c3">© 2026 LearnForge. Built for creators who teach what matters.</div></footer>'''

def stats_html():
    return '<section class="stats"><div class="container stats-grid">' + ''.join(f'<div class="stat"><strong>{n}</strong><span>{t}</span></div>' for n,t in stats) + '</div></section>'

def integrations_html():
    return '<section class="section alt"><div class="container"><div class="section-head"><div><span class="eyebrow">Integrations</span><h2>Connect your favorite tools.</h2><p class="intro">A clean integration layer lets your sales, marketing, analytics, and coaching stack work together.</p></div></div><div class="logo-grid">' + ''.join(f'<div class="logo reveal">{x}</div>' for x in integrations) + '</div></div></section>'

def testimonials_html(offset=0):
    ordered = testimonials[offset:] + testimonials[:offset]
    slides = ''.join(f'''<article class="testimonial"><div><div class="quote-mark">“</div><span class="badge">{tag}</span></div><div><blockquote>{quote}</blockquote><strong>{name}</strong><p>{org}</p></div></article>''' for name,org,tag,quote in ordered)
    return f'''<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Creator Stories</span><h2>Real businesses grow here.</h2><p class="intro">Hear how creators use LearnForge to scale education products without losing the human connection.</p></div><div data-carousel-count></div></div><div class="carousel" data-carousel><div class="testimonial-track"><div class="testimonial-strip">{slides}</div></div><div class="carousel-controls"><button class="circle-btn" data-prev aria-label="Previous testimonial">←</button><button class="circle-btn" data-next aria-label="Next testimonial">→</button></div></div></div></section>'''

def faq_html(items):
    return '<section class="section alt"><div class="container"><div class="section-head"><div><span class="eyebrow">FAQ</span><h2>Questions, answered.</h2></div></div><div class="faq" data-accordion>' + ''.join(f'<div class="faq-item"><button class="faq-q">{q}<span>+</span></button><div class="faq-a"><p>{a}</p></div></div>' for q,a in items) + '</div></div></section>'

